-- =====================================================================
-- 03_generate_facts.sql  --  the numbers
-- ---------------------------------------------------------------------
-- All data below is generated by formula, not copied from anywhere real.
-- It is *deterministic*: run it on any machine and you get identical
-- numbers, so an answer key written by your tutor will match your screen.
--
-- The randomness comes from md5() of the row's own keys rather than from
-- random(), which is what makes it repeatable.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Two tiny helper functions used only while building the dataset.
--   prand('anything')  -> a repeatable "random" number between 0 and 1
--   pnorm('anything')  -> a repeatable draw from a bell curve, mean 0, sd 1
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION prand(seed TEXT) RETURNS NUMERIC AS $$
    SELECT (('x' || substr(md5(seed), 1, 8))::bit(32)::bigint)::numeric / 4294967296.0;
$$ LANGUAGE sql IMMUTABLE;

CREATE OR REPLACE FUNCTION pnorm(seed TEXT) RETURNS NUMERIC AS $$
    SELECT ( prand(seed||'a') + prand(seed||'b') + prand(seed||'c') + prand(seed||'d')
           + prand(seed||'e') + prand(seed||'f') + prand(seed||'g') + prand(seed||'h')
           + prand(seed||'i') + prand(seed||'j') + prand(seed||'k') + prand(seed||'l') ) - 6.0;
$$ LANGUAGE sql IMMUTABLE;

-- =====================================================================
-- 1. DAILY SHARE PRICES
-- Prices follow a random walk: tomorrow's price = today's price x (1 + a
-- small drift + a random shock). Each company gets its own starting price,
-- expected annual return (drift) and volatility.
-- Weekends are excluded. Market holidays are NOT excluded -- a deliberate
-- imperfection you will discover when you build a trading calendar.
-- =====================================================================
INSERT INTO fact_price (company_id, price_date, open_px, high_px, low_px, close_px, volume)
WITH params AS (
    SELECT c.company_id, c.ticker,
           (80 + 60 * prand(c.ticker||'p0'))::numeric               AS start_px,
           (0.04 + 0.22 * prand(c.ticker||'drift'))::numeric        AS ann_drift,
           (0.16 + 0.30 * prand(c.ticker||'vol'))::numeric          AS ann_vol,
           (200000 + 4000000 * prand(c.ticker||'vol0'))::numeric    AS base_volume
    FROM dim_company c
),
days AS (
    SELECT d.date_key, ROW_NUMBER() OVER (ORDER BY d.date_key) AS t
    FROM dim_date d
    WHERE d.date_key BETWEEN DATE '2023-04-03' AND DATE '2026-06-30'
      AND d.is_weekday
),
steps AS (
    SELECT p.company_id, p.ticker, d.date_key, d.t, p.start_px, p.base_volume,
           p.ann_drift / 252.0
             + (p.ann_vol / sqrt(252.0)) * pnorm(p.ticker || ':' || d.t::text) AS log_ret
    FROM params p CROSS JOIN days d
),
walk AS (
    SELECT company_id, ticker, date_key, t, start_px, base_volume,
           SUM(log_ret) OVER (PARTITION BY company_id ORDER BY t
                              ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_ret
    FROM steps
),
px AS (
    SELECT company_id, ticker, date_key, t, base_volume,
           ROUND(start_px * exp(cum_ret), 4) AS close_px
    FROM walk
)
SELECT
    company_id,
    date_key,
    ROUND(close_px * (1 + 0.004 * pnorm(ticker||'o'||t::text)), 4)                  AS open_px,
    ROUND(close_px * (1 + 0.006 * abs(pnorm(ticker||'h'||t::text)) + 0.002), 4)     AS high_px,
    ROUND(close_px * (1 - 0.006 * abs(pnorm(ticker||'l'||t::text)) - 0.002), 4)     AS low_px,
    close_px,
    (base_volume * (0.55 + 0.9 * prand(ticker||'v'||t::text)))::bigint              AS volume
FROM px;

-- =====================================================================
-- 2. FX RATES (daily, quoted against INR)
-- =====================================================================
INSERT INTO fact_fx_rate (rate_date, from_ccy, to_ccy, rate)
SELECT d.date_key, x.ccy, 'INR',
       ROUND(x.base * exp(0.0001 * (d.date_key - DATE '2023-04-03')
                          + 0.05 * pnorm(x.ccy || d.date_key::text)), 6)
FROM dim_date d
CROSS JOIN (VALUES ('USD', 82.0), ('GBP', 103.0), ('EUR', 89.0), ('AED', 22.3)) AS x(ccy, base)
WHERE d.date_key BETWEEN DATE '2023-04-01' AND DATE '2026-06-30';

INSERT INTO fact_fx_rate (rate_date, from_ccy, to_ccy, rate)
SELECT rate_date, 'INR', from_ccy, ROUND(1.0 / rate, 6) FROM fact_fx_rate WHERE to_ccy = 'INR';


-- =====================================================================
-- 3. QUARTERLY FINANCIAL STATEMENTS  (FY24-Q1 .. FY26-Q4, 12 quarters)
-- ---------------------------------------------------------------------
-- This block is built exactly the way a real three-statement model is
-- built, which is why the three statements tie to each other:
--
--   * revenue is driven by a growth rate and a seasonal shape
--   * costs are driven by margin assumptions
--   * working capital is driven by DSO / DIO / DPO day assumptions
--   * fixed assets roll forward: opening PPE + capex - depreciation
--   * debt rolls forward: opening debt - repayment
--   * retained earnings roll forward: opening + profit - dividends
--   * CASH IS THE PLUG: cash = total liabilities + equity - other assets
--
-- Because cash is derived from the balance sheet identity rather than
-- guessed, the cash flow statement below reconciles to the penny. You will
-- be asked to prove that in the Module 12 reconciliation exercise -- and if
-- you ever find a quarter where it does not tie, that is a genuine bug
-- worth reporting, not a rounding excuse.
--
-- All amounts are in MILLIONS of the company's reporting currency.
-- =====================================================================
WITH RECURSIVE p AS (
    SELECT c.company_id, c.ticker, c.sector, c.shares_out_m,
           ROUND((400 + 3200 * prand(c.ticker||'rev'))::numeric, 2)          AS rev0,
           CASE c.sector
             WHEN 'Information Technology'  THEN 0.030 WHEN 'Health Care'    THEN 0.022
             WHEN 'Communication Services'  THEN 0.012 WHEN 'Financials'     THEN 0.018
             WHEN 'Consumer Discretionary'  THEN 0.016 WHEN 'Consumer Staples' THEN 0.011
             WHEN 'Industrials'             THEN 0.014 WHEN 'Utilities'      THEN 0.010
             WHEN 'Energy'                  THEN 0.008 ELSE 0.012 END
             + 0.010 * (prand(c.ticker||'g') - 0.5)                          AS g,
           CASE c.sector
             WHEN 'Information Technology'  THEN 0.70 WHEN 'Health Care'     THEN 0.58
             WHEN 'Communication Services'  THEN 0.55 WHEN 'Financials'      THEN 0.62
             WHEN 'Consumer Discretionary'  THEN 0.42 WHEN 'Consumer Staples' THEN 0.38
             WHEN 'Industrials'             THEN 0.28 WHEN 'Utilities'       THEN 0.35
             WHEN 'Energy'                  THEN 0.30 ELSE 0.24 END          AS gm,
           CASE c.sector
             WHEN 'Information Technology'  THEN 0.28 WHEN 'Health Care'     THEN 0.30
             WHEN 'Communication Services'  THEN 0.25 WHEN 'Financials'      THEN 0.30
             WHEN 'Consumer Discretionary'  THEN 0.26 WHEN 'Consumer Staples' THEN 0.22
             WHEN 'Industrials'             THEN 0.14 WHEN 'Utilities'       THEN 0.09
             WHEN 'Energy'                  THEN 0.10 ELSE 0.10 END          AS sga_pct,
           CASE c.sector
             WHEN 'Information Technology'  THEN 0.18 WHEN 'Health Care'     THEN 0.12
             ELSE 0.010 END                                                  AS rnd_pct,
           0.015                                                             AS other_opex_pct,
           CASE c.sector
             WHEN 'Utilities' THEN 0.14 WHEN 'Communication Services' THEN 0.15
             WHEN 'Energy'    THEN 0.12 WHEN 'Materials' THEN 0.09
             WHEN 'Industrials' THEN 0.07 WHEN 'Information Technology' THEN 0.04
             ELSE 0.05 END                                                   AS capex_pct,
           CASE c.sector
             WHEN 'Information Technology' THEN 65 WHEN 'Health Care' THEN 70
             WHEN 'Consumer Staples' THEN 25 WHEN 'Consumer Discretionary' THEN 30
             WHEN 'Financials' THEN 20 WHEN 'Communication Services' THEN 30
             ELSE 45 END::numeric                                            AS dso,
           CASE c.sector
             WHEN 'Information Technology' THEN 0 WHEN 'Financials' THEN 0
             WHEN 'Health Care' THEN 90 WHEN 'Consumer Staples' THEN 60
             WHEN 'Consumer Discretionary' THEN 75 WHEN 'Communication Services' THEN 10
             WHEN 'Utilities' THEN 15 ELSE 55 END::numeric                   AS dio,
           CASE c.sector
             WHEN 'Information Technology' THEN 35 WHEN 'Financials' THEN 30
             ELSE 50 END::numeric                                            AS dpo,
           0.25                                                              AS tax_rate,
           (0.075 + 0.03 * prand(c.ticker||'ir'))                            AS int_rate,
           0.020                                                             AS dep_rate_q,
           0.015                                                             AS amort_rate_q,
           CASE WHEN c.sector IN ('Consumer Discretionary','Consumer Staples')
                THEN 1.0 ELSE 0.4 END                                        AS season_amp,
           CASE WHEN prand(c.ticker||'div') > 0.45 THEN 0.20 ELSE 0.00 END   AS payout,
           CASE c.sector
             WHEN 'Information Technology' THEN 0.55 WHEN 'Communication Services' THEN 0.40
             ELSE 0.05 END                                                   AS defrev_pct
    FROM dim_company c
),
p2 AS (   -- opening (FY23-Q4, i.e. 31-Mar-2023) balance sheet
    SELECT p.*,
           ROUND(p.rev0 * 4 * p.dso / 365.0, 2)                     AS ar0,
           ROUND(p.rev0 * (1-p.gm) * 4 * p.dio / 365.0, 2)          AS inv0,
           ROUND(p.rev0 * 0.05, 2)                                  AS oca0,
           ROUND(p.rev0 * p.capex_pct * 4 * 9.0, 2)                 AS ppe0,
           ROUND(p.rev0 * 0.9 * prand(p.ticker||'gw'), 2)           AS gi0,
           ROUND(p.rev0 * 0.10, 2)                                  AS oa0,
           ROUND(p.rev0 * (1-p.gm) * 4 * p.dpo / 365.0, 2)          AS ap0,
           ROUND(p.rev0 * 0.04, 2)                                  AS accr0,
           ROUND(p.rev0 * p.defrev_pct, 2)                          AS dr0,
           ROUND(p.rev0 * 0.15, 2)                                  AS std0,
           ROUND(p.rev0 * (0.8 + 2.2 * prand(p.ticker||'lev')), 2)  AS ltd0,
           ROUND(p.rev0 * 0.06, 2)                                  AS ol0,
           ROUND(p.rev0 * 0.50, 2)                                  AS sc0,
           ROUND(p.rev0 * (1.2 + 1.5 * prand(p.ticker||'cash')), 2) AS cash0
    FROM p
),
p3 AS (   -- retained earnings is the free variable that makes the opening BS balance
    SELECT p2.*,
           ROUND(cash0 + ar0 + inv0 + oca0 + ppe0 + gi0 + oa0
                 - (ap0 + accr0 + dr0 + std0 + ltd0 + ol0) - sc0, 2) AS re0
    FROM p2
),
rec AS (
    -- anchor row: q = -1 carries only the opening balance sheet
    SELECT company_id, -1 AS q,
           0::numeric AS revenue, 0::numeric AS cogs, 0::numeric AS sga, 0::numeric AS rnd,
           0::numeric AS other_opex, 0::numeric AS dep, 0::numeric AS amort,
           0::numeric AS int_exp, 0::numeric AS int_inc, 0::numeric AS tax, 0::numeric AS ni,
           0::numeric AS dividends, 0::numeric AS capex, 0::numeric AS debt_repaid,
           cash0 AS cash, ar0 AS ar, inv0 AS inv, oca0 AS oca, ppe0 AS ppe, gi0 AS gi,
           ap0 AS ap, accr0 AS accr, dr0 AS dr, ltd0 AS ltd, re0 AS re
    FROM p3
    UNION ALL
    SELECT
        r.company_id, r.q + 1,
        v.revenue, v.cogs, v.sga, v.rnd, v.other_opex, v.dep, v.amort,
        v.int_exp, v.int_inc, v.tax, v.ni, v.dividends, v.capex, v.debt_repaid,
        -- CASH IS THE PLUG: liabilities + equity - all non-cash assets
        ROUND( (v.ap_e + v.accr_e + v.dr_e + p3.std0 + v.ltd_e + p3.ol0)
             + (p3.sc0 + v.re_e)
             - (v.ar_e + v.inv_e + v.oca_e + v.ppe_e + v.gi_e + p3.oa0), 2),
        v.ar_e, v.inv_e, v.oca_e, v.ppe_e, v.gi_e, v.ap_e, v.accr_e, v.dr_e, v.ltd_e, v.re_e
    FROM rec r
    JOIN p3 ON p3.company_id = r.company_id
    CROSS JOIN LATERAL (
        SELECT
            rv                                                              AS revenue,
            ROUND(rv * (1 - p3.gm), 2)                                      AS cogs,
            ROUND(rv * p3.sga_pct, 2)                                       AS sga,
            ROUND(rv * p3.rnd_pct, 2)                                       AS rnd,
            ROUND(rv * p3.other_opex_pct, 2)                                AS other_opex,
            dp                                                              AS dep,
            am                                                              AS amort,
            ie                                                              AS int_exp,
            ii                                                              AS int_inc,
            tx                                                              AS tax,
            ROUND(pt - tx, 2)                                               AS ni,
            ROUND(GREATEST(pt - tx, 0) * p3.payout, 2)                      AS dividends,
            cx                                                              AS capex,
            dr_pay                                                          AS debt_repaid,
            ROUND(rv * 4 * p3.dso / 365.0, 2)                               AS ar_e,
            ROUND(rv * (1-p3.gm) * 4 * p3.dio / 365.0, 2)                   AS inv_e,
            ROUND(rv * 0.05, 2)                                             AS oca_e,
            ROUND(r.ppe + cx - dp, 2)                                       AS ppe_e,
            ROUND(r.gi - am, 2)                                             AS gi_e,
            ROUND(rv * (1-p3.gm) * 4 * p3.dpo / 365.0, 2)                   AS ap_e,
            ROUND(rv * 0.04, 2)                                             AS accr_e,
            ROUND(rv * p3.defrev_pct, 2)                                    AS dr_e,
            ROUND(r.ltd - dr_pay, 2)                                        AS ltd_e,
            ROUND(r.re + (pt - tx) - GREATEST(pt - tx, 0) * p3.payout, 2)   AS re_e
        FROM (
            SELECT rv, dp, am, ie, ii, cx, dr_pay,
                   ROUND(rv*p3.gm - rv*p3.sga_pct - rv*p3.rnd_pct - rv*p3.other_opex_pct
                         - dp - am - ie + ii, 2)                            AS pt,
                   ROUND(GREATEST(rv*p3.gm - rv*p3.sga_pct - rv*p3.rnd_pct
                                  - rv*p3.other_opex_pct - dp - am - ie + ii, 0)
                         * p3.tax_rate, 2)                                  AS tx
            FROM (
                SELECT
                    ROUND(p3.rev0 * power(1 + p3.g, r.q + 1)
                          * (1 + p3.season_amp * (ARRAY[-0.040,-0.010,0.030,0.020])[((r.q+1) % 4) + 1])
                          * (1 + 0.025 * pnorm(p3.ticker||'q'||(r.q+1)::text)), 2)  AS rv,
                    ROUND(r.ppe * p3.dep_rate_q, 2)                                 AS dp,
                    ROUND(r.gi  * p3.amort_rate_q, 2)                               AS am,
                    ROUND((r.ltd + p3.std0) * p3.int_rate / 4.0, 2)                 AS ie,
                    ROUND(r.cash * 0.006, 2)                                        AS ii,
                    ROUND(p3.rev0 * power(1 + p3.g, r.q + 1) * p3.capex_pct, 2)     AS cx,
                    ROUND(p3.ltd0 * 0.02, 2)                                        AS dr_pay
            ) AS d0
        ) AS d1
    ) AS v
    WHERE r.q < 11
),
final AS (
    SELECT r.*,
           (DATE '2023-04-01' + ((r.q + 1) * 3) * INTERVAL '1 month' - INTERVAL '1 day')::date AS period_end,
           LAG(r.cash) OVER w AS cash_b, LAG(r.ar)  OVER w AS ar_b,  LAG(r.inv) OVER w AS inv_b,
           LAG(r.oca)  OVER w AS oca_b,  LAG(r.ppe) OVER w AS ppe_b, LAG(r.gi)  OVER w AS gi_b,
           LAG(r.ap)   OVER w AS ap_b,   LAG(r.accr) OVER w AS accr_b, LAG(r.dr) OVER w AS dr_b,
           LAG(r.ltd)  OVER w AS ltd_b,  LAG(r.re)  OVER w AS re_b
    FROM rec r
    WINDOW w AS (PARTITION BY r.company_id ORDER BY r.q)
)
SELECT f.*,
       ROUND(f.revenue - f.cogs - f.sga - f.rnd - f.other_opex, 2)                    AS ebitda,
       ROUND(f.revenue - f.cogs - f.sga - f.rnd - f.other_opex - f.dep - f.amort, 2)  AS ebit,
       ROUND(f.revenue - f.cogs - f.sga - f.rnd - f.other_opex - f.dep - f.amort
             - f.int_exp + f.int_inc, 2)                                              AS pretax,
       p3.std0, p3.ol0, p3.sc0, p3.oa0
INTO TEMPORARY TABLE build_fs_model
FROM final f JOIN p3 ON p3.company_id = f.company_id
WHERE f.q >= 0;

-- --- Income statement -------------------------------------------------
INSERT INTO fs_income_statement
SELECT m.company_id, m.period_end, 'Q',
       m.revenue, m.cogs, ROUND(m.revenue - m.cogs, 2),
       m.sga, m.rnd, m.other_opex, m.ebitda, m.dep, m.amort, m.ebit,
       m.int_exp, m.int_inc, 0, m.pretax, m.tax, m.ni,
       c.shares_out_m,
       ROUND(m.ni / NULLIF(c.shares_out_m, 0), 4)
FROM build_fs_model m JOIN dim_company c USING (company_id);

-- --- Balance sheet ----------------------------------------------------
INSERT INTO fs_balance_sheet
SELECT m.company_id, m.period_end,
       m.cash, m.ar, m.inv, m.oca, m.ppe, m.gi, m.oa0,
       ROUND(m.cash + m.ar + m.inv + m.oca + m.ppe + m.gi + m.oa0, 2)                AS total_assets,
       m.ap, m.accr, m.dr, m.std0, m.ltd, m.ol0,
       ROUND(m.ap + m.accr + m.dr + m.std0 + m.ltd + m.ol0, 2)                       AS total_liabilities,
       m.sc0, m.re,
       ROUND(m.sc0 + m.re, 2)                                                        AS total_equity
FROM build_fs_model m;

-- --- Cash flow statement ---------------------------------------------
-- Built from the movement in each balance sheet line, which is exactly how
-- an "indirect method" cash flow statement is built in practice.
INSERT INTO fs_cash_flow
SELECT m.company_id, m.period_end,
       m.ni,
       ROUND(m.dep + m.amort, 2)                                                     AS dep_and_amort,
       ROUND(-(m.ar - m.ar_b) - (m.inv - m.inv_b) - (m.oca - m.oca_b)
             + (m.ap - m.ap_b) + (m.accr - m.accr_b) + (m.dr - m.dr_b), 2)           AS change_in_wc,
       0                                                                             AS other_operating,
       ROUND(m.ni + m.dep + m.amort
             - (m.ar - m.ar_b) - (m.inv - m.inv_b) - (m.oca - m.oca_b)
             + (m.ap - m.ap_b) + (m.accr - m.accr_b) + (m.dr - m.dr_b), 2)           AS cfo,
       ROUND(-m.capex, 2)                                                            AS capex,
       0                                                                             AS other_investing,
       ROUND(-m.capex, 2)                                                            AS cfi,
       0                                                                             AS debt_raised,
       ROUND(-m.debt_repaid, 2)                                                      AS debt_repaid,
       ROUND(-m.dividends, 2)                                                        AS dividends_paid,
       0                                                                             AS equity_issued,
       ROUND(-m.debt_repaid - m.dividends, 2)                                        AS cff,
       ROUND(m.cash - m.cash_b, 2)                                                   AS net_change_cash
FROM build_fs_model m;

DROP TABLE build_fs_model;

-- =====================================================================
-- 4. OUR COMPANY'S GENERAL LEDGER, BUDGET AND HEADCOUNT
-- ---------------------------------------------------------------------
-- "Our company" is Meridian Softworks Ltd (company_id 7), a subscription
-- software business. This is the FP&A playground: actual vs budget,
-- variance analysis, cost-centre reporting, month-end close.
--
-- Every journal has exactly two lines and debits always equal credits.
-- That is not decoration -- it is the rule that makes a ledger a ledger,
-- and you will write the query that proves it holds.
--
-- Three anomalies are planted on purpose. They are the kind of thing a
-- real analyst is paid to notice. No, you are not told where they are.
-- =====================================================================
CREATE TEMPORARY TABLE build_gl_driver AS
WITH months AS (
    SELECT m::date AS month_start,
           ROW_NUMBER() OVER (ORDER BY m) - 1 AS mi,
           EXTRACT(MONTH FROM m)::int AS cal_month,
           CASE WHEN EXTRACT(MONTH FROM m) >= 4 THEN EXTRACT(YEAR FROM m)::int + 1
                ELSE EXTRACT(YEAR FROM m)::int END AS fiscal_year,
           ((EXTRACT(MONTH FROM m)::int + 8) % 12) + 1 AS fiscal_month
    FROM generate_series(DATE '2023-04-01', DATE '2026-06-01', INTERVAL '1 month') m
),
map AS (   -- which department books which account, and at what relative size
    SELECT * FROM (VALUES
        ( 1, 3, 0.62), ( 1, 4, 0.38),                                   -- subscription revenue
        ( 2, 3, 0.55), ( 2, 4, 0.45),                                   -- services revenue
        ( 3, 3, 1.00),                                                  -- hardware resale
        ( 4, 1, 1.00),                                                  -- hosting
        ( 5, 6, 1.00),                                                  -- support salaries
        ( 6, 1, 1.00),                                                  -- third party licences
        ( 7, 1, 0.42), ( 7, 2, 0.10), ( 7, 3, 0.14), ( 7, 4, 0.09),
        ( 7, 5, 0.06), ( 7, 6, 0.08), ( 7, 7, 0.06), ( 7, 8, 0.05),     -- salaries
        ( 8, 1, 0.42), ( 8, 2, 0.10), ( 8, 3, 0.14), ( 8, 4, 0.09),
        ( 8, 5, 0.06), ( 8, 6, 0.08), ( 8, 7, 0.06), ( 8, 8, 0.05),     -- benefits
        ( 9, 8, 1.00),                                                  -- recruitment
        (10, 5, 1.00),                                                  -- marketing programmes
        (11, 3, 0.60), (11, 4, 0.40),                                   -- sales commission
        (12, 3, 0.35), (12, 4, 0.30), (12, 5, 0.20), (12, 7, 0.15),     -- travel
        (13, 8, 1.00), (14, 7, 1.00), (15, 1, 0.55), (15, 7, 0.45),
        (16, 7, 1.00), (17, 8, 1.00), (18, 7, 1.00)
    ) AS t(account_id, dept_id, share)
),
base AS (
    SELECT * FROM (VALUES
        ( 1, 30000000.0, 0.0180), ( 2,  4200000.0, 0.0120), ( 3,  1500000.0, 0.0040),
        ( 4,  4100000.0, 0.0165), ( 5,  2600000.0, 0.0140), ( 6,  1900000.0, 0.0150),
        ( 7, 11500000.0, 0.0155), ( 8,  2300000.0, 0.0155), ( 9,   950000.0, 0.0100),
        (10,  3800000.0, 0.0170), (11,  1750000.0, 0.0180), (12,   880000.0, 0.0110),
        (13,  1450000.0, 0.0035), (14,   720000.0, 0.0060), (15,   640000.0, 0.0130),
        (16,   310000.0, 0.0040), (17,   210000.0, 0.0030), (18,  1100000.0, 0.0090)
    ) AS t(account_id, base_amt, mgrowth)
)
SELECT mo.month_start, mo.mi, mo.fiscal_year, mo.fiscal_month,
       mp.account_id, mp.dept_id,
       a.category, a.normal_balance,
       -- the clean plan number: base x growth x seasonality
       ROUND((b.base_amt * mp.share * power(1 + b.mgrowth, mo.mi)
              * (1 + CASE WHEN a.category = 'Revenue' THEN 0.05 ELSE 0.03 END
                        * sin(2 * pi() * (mo.cal_month - 3) / 12.0)))::numeric, 2) AS driver_amt
FROM months mo
CROSS JOIN map mp
JOIN base b       ON b.account_id  = mp.account_id
JOIN dim_account a ON a.account_id = mp.account_id;

-- --- Actuals: the plan, plus real-life noise, plus three planted anomalies
INSERT INTO gl_journal_line
    (line_id, journal_id, entry_date, fiscal_year, fiscal_month, account_id, dept_id,
     description, debit, credit, source)
WITH txns AS (
    SELECT d.*,
           g.n AS txn_no,
           ROW_NUMBER() OVER (ORDER BY d.month_start, d.account_id, d.dept_id, g.n) AS journal_id,
           ROUND(
             d.driver_amt / (3 + (d.account_id + d.dept_id) % 3)
             * (1 + 0.10 * pnorm(d.month_start::text||d.account_id||d.dept_id||g.n))
             -- planted anomaly 1: professional fees blow up in Nov-2025 (a litigation bill)
             * CASE WHEN d.account_id = 14 AND d.month_start = DATE '2025-11-01' THEN 7.5 ELSE 1 END
             -- planted anomaly 2: marketing overspends all of FY26 Q3
             * CASE WHEN d.account_id = 10 AND d.month_start BETWEEN DATE '2025-10-01'
                                                                AND DATE '2025-12-01' THEN 1.6 ELSE 1 END
             -- planted anomaly 3: hosting cost steps up permanently from Jan-2026 (a re-platforming)
             * CASE WHEN d.account_id = 4 AND d.month_start >= DATE '2026-01-01' THEN 1.35 ELSE 1 END
           , 2) AS amt
    FROM build_gl_driver d
    CROSS JOIN LATERAL generate_series(1, 3 + (d.account_id + d.dept_id) % 3) AS g(n)
),
posted AS (
    SELECT t.*,
           (t.month_start + (((t.txn_no * 7 + t.account_id * 3) % 27))::int)::date AS entry_date,
           CASE WHEN t.category = 'Revenue' THEN 22          -- Accounts Receivable
                WHEN t.account_id IN (5,7,8) THEN 21         -- Cash at Bank (payroll)
                WHEN t.account_id = 18      THEN 24          -- PPE (depreciation)
                ELSE 25 END AS contra_account_id,            -- Accounts Payable
           CASE WHEN t.category = 'Revenue' THEN 'AR'
                WHEN t.account_id IN (5,7,8) THEN 'Payroll'
                WHEN t.account_id = 18 THEN 'Manual'
                ELSE 'AP' END AS source
    FROM txns t
)
SELECT line_id, journal_id, entry_date, fiscal_year, fiscal_month, account_id, dept_id,
       description, debit, credit, source
FROM (
    -- line 1: the account itself
    SELECT p.journal_id * 2 - 1 AS line_id, p.journal_id, p.entry_date,
           p.fiscal_year, p.fiscal_month, p.account_id, p.dept_id,
           a.account_name || ' - ' || TO_CHAR(p.month_start, 'Mon YYYY') AS description,
           CASE WHEN a.normal_balance = 'DR' THEN p.amt ELSE 0 END AS debit,
           CASE WHEN a.normal_balance = 'CR' THEN p.amt ELSE 0 END AS credit,
           p.source
    FROM posted p JOIN dim_account a ON a.account_id = p.account_id
    UNION ALL
    -- line 2: the contra side, so every journal balances
    SELECT p.journal_id * 2 AS line_id, p.journal_id, p.entry_date,
           p.fiscal_year, p.fiscal_month, p.contra_account_id, p.dept_id,
           ca.account_name || ' - contra' AS description,
           CASE WHEN a.normal_balance = 'DR' THEN 0 ELSE p.amt END AS debit,
           CASE WHEN a.normal_balance = 'DR' THEN p.amt ELSE 0 END AS credit,
           p.source
    FROM posted p
    JOIN dim_account a  ON a.account_id  = p.account_id
    JOIN dim_account ca ON ca.account_id = p.contra_account_id
) x;

-- --- Budget: the plan as it was locked before the year started.
-- Finance never budgets to the rupee, so numbers are rounded to the
-- nearest 10,000 and carry a small planning bias by cost category.
INSERT INTO gl_budget (fiscal_year, fiscal_month, account_id, dept_id, budget_amount, version)
SELECT fiscal_year, fiscal_month, account_id, dept_id,
       ROUND( driver_amt
              * CASE category WHEN 'Revenue' THEN 1.06      -- sales targets are stretched
                              WHEN 'COGS'    THEN 0.97
                              ELSE 1.02 END                  -- cost budgets carry a cushion
              / 10000.0 ) * 10000.0,
       'Budget v1'
FROM build_gl_driver
WHERE fiscal_year >= 2025;

INSERT INTO gl_headcount (fiscal_year, fiscal_month, dept_id, headcount, avg_salary)
SELECT d.fiscal_year, d.fiscal_month, d.dept_id,
       GREATEST(1, ROUND(SUM(d.driver_amt) / 95000.0))::int,
       ROUND(78000 * power(1.0055, MAX(d.mi)), 2)
FROM build_gl_driver d
WHERE d.account_id = 7
GROUP BY d.fiscal_year, d.fiscal_month, d.dept_id;

DROP TABLE build_gl_driver;

-- =====================================================================
-- 5. SUBSCRIPTION BUSINESS: subscriptions, invoices, payments
-- ---------------------------------------------------------------------
-- Customers sign up, pay monthly or annually, and some of them leave.
-- How long a customer stays is drawn from an exponential "survival" curve,
-- with big customers churning far more slowly than small ones -- which is
-- what makes cohort retention curves in this dataset look like real ones.
--
-- The data cut-off is 30-Jun-2026. Anything after that has not happened yet.
-- =====================================================================
INSERT INTO saas_subscription
    (subscription_id, customer_id, plan, mrr, seats, start_date, end_date, cancel_reason, billing_term)
WITH s AS (
    SELECT c.customer_id, c.segment, c.signup_date,
           CASE c.segment WHEN 'Enterprise' THEN 0.008
                          WHEN 'Mid-Market' THEN 0.018
                          ELSE 0.035 END                                  AS monthly_churn_hazard,
           CASE c.segment WHEN 'Enterprise' THEN 'Enterprise'
                          WHEN 'Mid-Market' THEN
                               CASE WHEN prand(c.customer_id||'plan') > 0.5 THEN 'Scale' ELSE 'Growth' END
                          ELSE CASE WHEN prand(c.customer_id||'plan') > 0.65 THEN 'Growth' ELSE 'Starter' END
           END                                                            AS plan,
           CASE c.segment WHEN 'Enterprise' THEN 120 + (prand(c.customer_id||'seat')*400)::int
                          WHEN 'Mid-Market' THEN  25 + (prand(c.customer_id||'seat')*95)::int
                          ELSE                     3 + (prand(c.customer_id||'seat')*17)::int
           END                                                            AS seats
    FROM dim_customer c
),
t AS (
    SELECT s.*,
           GREATEST(1, CEIL(-LN(GREATEST(prand(s.customer_id||'life'), 0.0001))
                            / s.monthly_churn_hazard))::int               AS tenure_months,
           CASE s.plan WHEN 'Starter' THEN 850 WHEN 'Growth' THEN 1900
                       WHEN 'Scale'   THEN 4200 ELSE 9500 END             AS price_per_seat_band
    FROM s
)
SELECT t.customer_id                                                       AS subscription_id,
       t.customer_id,
       t.plan,
       ROUND(( t.seats * CASE t.plan WHEN 'Starter' THEN 320 WHEN 'Growth' THEN 520
                                     WHEN 'Scale' THEN 760 ELSE 1050 END
             * (0.85 + 0.30 * prand(t.customer_id||'disc')) )::numeric, 2) AS mrr,
       t.seats,
       t.signup_date                                                       AS start_date,
       CASE WHEN (t.signup_date + (t.tenure_months || ' month')::interval)::date <= DATE '2026-06-30'
            THEN (t.signup_date + (t.tenure_months || ' month')::interval)::date
            ELSE NULL END                                                  AS end_date,
       CASE WHEN (t.signup_date + (t.tenure_months || ' month')::interval)::date <= DATE '2026-06-30'
            THEN (ARRAY['Price','Switched to competitor','Budget cut','Low usage',
                        'Company shut down','Merged/acquired','Poor support experience'])
                 [1 + (t.customer_id * 5) % 7]
            ELSE NULL END                                                  AS cancel_reason,
       CASE WHEN t.segment = 'Enterprise' OR prand(t.customer_id||'term') > 0.62
            THEN 'Annual' ELSE 'Monthly' END                               AS billing_term
FROM t;

-- --- Invoices: one per billing period, from the start date to the cut-off
INSERT INTO saas_invoice (invoice_id, customer_id, invoice_date, due_date, amount, currency, status)
WITH sched AS (
    SELECT s.subscription_id, s.customer_id, s.mrr, s.billing_term,
           gs::date AS invoice_date
    FROM saas_subscription s
    CROSS JOIN LATERAL generate_series(
            s.start_date,
            LEAST(COALESCE(s.end_date, DATE '2026-06-30'), DATE '2026-06-30'),
            CASE WHEN s.billing_term = 'Annual' THEN INTERVAL '12 month' ELSE INTERVAL '1 month' END
    ) gs
),
inv AS (
    SELECT ROW_NUMBER() OVER (ORDER BY invoice_date, customer_id) AS invoice_id,
           sched.*,
           (invoice_date + 30)::date AS due_date,
           ROUND(CASE WHEN billing_term = 'Annual' THEN mrr * 12 * 0.90 ELSE mrr END, 2) AS amount,
           -- how many days this customer takes to pay
           (5 + (45 * prand(customer_id||invoice_date::text||'pay'))::int)               AS pay_delay
    FROM sched
)
SELECT invoice_id, customer_id, invoice_date, due_date, amount, 'INR',
       CASE WHEN prand(invoice_id||'wo') < 0.012 AND invoice_date < DATE '2026-02-01' THEN 'Written Off'
            WHEN (invoice_date + pay_delay) <= DATE '2026-06-30'                       THEN 'Paid'
            ELSE 'Open' END
FROM inv;

INSERT INTO saas_payment (payment_id, invoice_id, payment_date, amount, method)
SELECT i.invoice_id, i.invoice_id,
       (i.invoice_date + (5 + (45 * prand(i.customer_id||i.invoice_date::text||'pay'))::int))::date,
       i.amount,
       (ARRAY['NEFT','UPI','Credit Card','Cheque','Direct Debit'])[1 + (i.invoice_id * 3) % 5]
FROM saas_invoice i
WHERE i.status = 'Paid';

-- =====================================================================
-- 6. PORTFOLIO: trades and quarter-end holdings
-- =====================================================================
INSERT INTO pf_trade (trade_id, portfolio_id, company_id, trade_date, side, quantity, price, fees)
WITH universe AS (
    SELECT 1 AS portfolio_id, company_id FROM dim_company WHERE company_id BETWEEN 1 AND 12 AND company_id % 2 = 1
    UNION ALL
    SELECT 2, company_id FROM dim_company WHERE company_id BETWEEN 1 AND 12 AND company_id % 2 = 0
    UNION ALL
    SELECT 3, company_id FROM dim_company WHERE company_id BETWEEN 13 AND 20
),
raw AS (
    SELECT u.portfolio_id, u.company_id, g.n,
           (DATE '2023-04-03' + ((prand(u.portfolio_id||':'||u.company_id||':'||g.n||'d') * 1150)::int))::date AS want_date,
           CASE WHEN prand(u.portfolio_id||':'||u.company_id||':'||g.n||'s') > 0.42 THEN 'BUY' ELSE 'SELL' END AS side,
           (100 * (5 + (prand(u.portfolio_id||':'||u.company_id||':'||g.n||'q') * 45)::int))::numeric          AS quantity
    FROM universe u CROSS JOIN generate_series(1, 8) g(n)
),
snapped AS (   -- move each trade to the nearest day the market was open
    SELECT r.*, (SELECT MIN(p.price_date) FROM fact_price p
                 WHERE p.company_id = r.company_id AND p.price_date >= r.want_date) AS trade_date
    FROM raw r
)
SELECT ROW_NUMBER() OVER (ORDER BY s.trade_date, s.portfolio_id, s.company_id)::int,
       s.portfolio_id, s.company_id, s.trade_date, s.side, s.quantity,
       px.close_px,
       ROUND(s.quantity * px.close_px * 0.0012, 2)
FROM snapped s
JOIN fact_price px ON px.company_id = s.company_id AND px.price_date = s.trade_date
WHERE s.trade_date IS NOT NULL;

INSERT INTO pf_holding (portfolio_id, company_id, as_of_date, quantity, cost_basis)
WITH qends AS (
    SELECT date_key FROM dim_date
    WHERE is_quarter_end AND date_key BETWEEN DATE '2023-06-30' AND DATE '2026-06-30'
),
pos AS (
    SELECT q.date_key AS as_of_date, t.portfolio_id, t.company_id,
           SUM(CASE WHEN t.side = 'BUY' THEN t.quantity ELSE -t.quantity END)                  AS quantity,
           SUM(CASE WHEN t.side = 'BUY' THEN t.quantity * t.price ELSE -t.quantity * t.price END) AS cost_basis
    FROM qends q
    JOIN pf_trade t ON t.trade_date <= q.date_key
    GROUP BY 1, 2, 3
)
SELECT portfolio_id, company_id, as_of_date, quantity, ROUND(cost_basis, 2)
FROM pos WHERE quantity <> 0;

